begin;
set local role service_role;
do $$
<<batch_transaction_test>>
declare own uuid:=gen_random_uuid(); other_owner uuid:=gen_random_uuid(); company1 uuid; company2 uuid; lic1 uuid; lic2 uuid;
 today date:=(now() at time zone 'America/Sao_Paulo')::date; q jsonb; reserved jsonb; batch_id uuid; pay jsonb; result jsonb;
 expiry1 timestamptz; expiry2 timestamptz; event_prefix text:='batch_test_'||gen_random_uuid(); payment_id text:='pay_test_'||gen_random_uuid(); key_id uuid:=gen_random_uuid(); period_days integer;
begin
 update public.billing_product set monthly_price=100,semiannual_price=550,annual_price=1000 where id=true;
 insert into public.portal_users(id,nome,email,senha_hash,status) values(own,'Batch test',own||'@example.invalid','not-a-login','active'),(other_owner,'Other test',other_owner||'@example.invalid','not-a-login','active');
 insert into public.companies(nome) values('TEST COMPANY 1') returning id into company1;
 insert into public.companies(nome) values('TEST COMPANY 2') returning id into company2;
 insert into public.licenses(company_id,chave,vencimento) values(company1,'TEST-'||gen_random_uuid(),(today+5)::timestamp at time zone 'America/Sao_Paulo') returning id into lic1;
 insert into public.licenses(company_id,chave,vencimento) values(company2,'TEST-'||gen_random_uuid(),(today+15)::timestamp at time zone 'America/Sao_Paulo') returning id into lic2;
 insert into public.portal_user_licenses(user_id,license_id) values(own,lic1),(own,lic2);
 q:=public.mlsh_batch_quote(own,array[lic1,lic2],1);
 period_days:=(q->>'reference_days')::integer;
 if (q->>'total')::numeric<>100+round(100::numeric*(period_days+10)/period_days,2) then raise exception 'Proportional calculation mismatch'; end if;
 if (q->>'target_date')::date<>((today+15)+interval '1 month')::date then raise exception 'Common date mismatch'; end if;
 begin perform public.mlsh_batch_quote(other_owner,array[lic1,lic2],1);raise exception 'Ownership check failed';exception when others then if sqlerrm not like '%license_unavailable%' then raise; end if;end;
 reserved:=public.mlsh_reserve_batch(own,array[lic1,lic2],1,key_id,'sandbox');batch_id:=(reserved->'batch'->>'id')::uuid;
 if reserved->>'created'<>'true' then raise exception 'Batch reserve failed'; end if;
 if public.mlsh_reserve_batch(own,array[lic1,lic2],1,key_id,'sandbox')->>'created'<>'false' then raise exception 'Duplicate reservation'; end if;
 begin perform public.mlsh_reserve_batch(own,array[lic1,lic2],1,gen_random_uuid(),'sandbox');raise exception 'Duplicate pending allowed';exception when others then if sqlerrm not like '%license_reserved%' then raise; end if;end;
 pay:=jsonb_build_object('id',payment_id,'externalReference','mlsh_batch_'||batch_id,'checkoutSession','test_checkout_'||batch_id,'customer','test_customer','status','RECEIVED','value',(q->>'total')::numeric,'billingType','PIX');
 insert into public.billing_webhook_events(id,environment,event,payment_id) values(event_prefix||'_wrong','sandbox','PAYMENT_RECEIVED',payment_id);
 result:=public.mlsh_apply_batch_payment(event_prefix||'_wrong','sandbox',pay||jsonb_build_object('value',1));
 if result->>'status'<>'review' then raise exception 'Wrong total accepted'; end if;
 insert into public.billing_webhook_events(id,environment,event,payment_id) values(event_prefix,'sandbox','PAYMENT_RECEIVED',payment_id);
 result:=public.mlsh_apply_batch_payment(event_prefix,'sandbox',pay);
 if result->>'status'<>'processed' then raise exception 'Batch payment failed: %',result; end if;
 select vencimento into expiry1 from public.licenses where id=lic1;select vencimento into expiry2 from public.licenses where id=lic2;
 if expiry1<>expiry2 or (expiry1 at time zone 'America/Sao_Paulo')::date<>(q->>'target_date')::date then raise exception 'Licenses did not align'; end if;
 if (select count(*) from public.payments where payments.batch_id=batch_transaction_test.batch_id)<>1 then raise exception 'Batch must create one payment'; end if;
 insert into public.billing_webhook_events(id,environment,event,payment_id) values(event_prefix||'_duplicate','sandbox','PAYMENT_CONFIRMED',payment_id);
 result:=public.mlsh_apply_batch_payment(event_prefix||'_duplicate','sandbox',pay);
 if result->>'duplicate'<>'true' or (select vencimento from public.licenses where id=lic1)<>expiry1 then raise exception 'Duplicate extended licenses'; end if;
 begin perform public.mlsh_batch_quote(own,array[lic1,lic2],1);raise exception 'Stacking renewal allowed';exception when others then if sqlerrm not like '%renewal_too_early%' then raise; end if;end;
 update public.licenses set vencimento=(today+16)::timestamp at time zone 'America/Sao_Paulo' where id=lic2;
 begin perform public.mlsh_batch_quote(own,array[lic1,lic2],1);raise exception 'Sixteenth day allowed';exception when others then if sqlerrm not like '%renewal_too_early%' then raise; end if;end;
 update public.licenses set vencimento=(today+15)::timestamp at time zone 'America/Sao_Paulo' where id in (lic1,lic2);
 select vencimento into expiry1 from public.licenses where id=lic1;
 perform public.mlsh_batch_quote(own,array[lic1,lic2],12);
 reserved:=public.mlsh_reserve_batch(own,array[lic1,lic2],6,gen_random_uuid(),'sandbox');batch_id:=(reserved->'batch'->>'id')::uuid;
 update public.licenses set vencimento=vencimento+interval '1 day' where id=lic2;
 pay:=pay||jsonb_build_object('id',payment_id||'_changed','externalReference','mlsh_batch_'||batch_id,'checkoutSession','test_checkout_'||batch_id,'value',(reserved->'batch'->>'expected_total')::numeric);
 insert into public.billing_webhook_events(id,environment,event,payment_id) values(event_prefix||'_changed','sandbox','PAYMENT_RECEIVED',payment_id||'_changed');
 result:=public.mlsh_apply_batch_payment(event_prefix||'_changed','sandbox',pay);
 if result->>'status'<>'review' or (select vencimento from public.licenses where id=lic1)<>expiry1 then raise exception 'Partial application after license change'; end if;
 perform public.mlsh_close_unpaid_batch(batch_id,'cancelled');
 if exists(select 1 from public.billing_batch_items i where i.batch_id=batch_transaction_test.batch_id and state='pending') then raise exception 'Cancelled batch still reserved'; end if;
 if has_function_privilege('anon','public.mlsh_apply_batch_payment(text,text,jsonb)','execute') then raise exception 'Anonymous payment function'; end if;
end $$;
rollback;
